-- نمایه‌های داده «پرونده حقوقی» (HTS: سیستم حقوقی - عملیات - پرونده حقوقی / گزارشات - گزارش کلی پرونده ها)
-- هر دو نمایه روی همان صفحه List موجودیت JudicialFile هستند. Idempotent.
-- دسترسی نقش‌ها/منو: Seed_Law_RoleAccess_Menu.sql
-- اجرا با Unicode:  sqlcmd -S <server> -d HavayarApp -C -b -I -f 65001 -i "Data\Scripts\Seed_Law_JudicialFile_DataProfiles.sql"

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRANSACTION;
BEGIN TRY

    DECLARE @Now DATETIME2 = GETDATE();
    DECLARE @NowShamsi NVARCHAR(30) = CONVERT(NVARCHAR(30), @Now, 120);
    DECLARE @SeedUser NVARCHAR(150) = N'seed-law-judicialfile-dataprofile';
    DECLARE @EntityFullName NVARCHAR(200) = N'entities.app.law.judicialfile';
    DECLARE @Name NVARCHAR(200), @Title NVARCHAR(200);
    DECLARE @QueryJson NVARCHAR(MAX), @ColumnsJson NVARCHAR(MAX), @ActionOptions NVARCHAR(MAX);
    DECLARE @Buttons NVARCHAR(MAX), @Events NVARCHAR(MAX), @ProfileId BIGINT;

    -- ================= Law_JudicialFile_List =================
    SET @Name = N'Law_JudicialFile_List';
    SET @Title = N'لیست پرونده های حقوقی';
    SET @QueryJson = N'{"Tables": [], "Relations": [], "Filters": [], "CustomConditions": [], "CustomQuery": "DECLARE @CuId BIGINT = TRY_CAST(@CurrentUserId AS BIGINT);\nDECLARE @HasFull BIT = CASE WHEN EXISTS (\n    SELECT 1\n    FROM system.[User] u\n    CROSS APPLY OPENJSON(ISNULL(u.RoleIds, N''[]'')) j\n    INNER JOIN system.Role r ON r.Id = TRY_CAST(j.value AS bigint)\n    WHERE u.Id = @CuId\n      AND r.Name IN (N''admin'', N''Law.JudicialFile.Full'')\n) THEN 1 ELSE 0 END;\n--!--mainsection\nSELECT\n    [t1].[Id] AS [t1_Id],\n    [t1].[CurrentStatus] AS [t1_CurrentStatus],\n    CASE [t1].[CurrentStatus] WHEN 1 THEN N''مختومه بنفع شرکت'' WHEN 2 THEN N''مختومه بر علیه شرکت'' WHEN 3 THEN N''مطرح رسیدگی'' END AS [t1_CurrentStatusTitle],\n    [t1].[JudicialFileCode] AS [t1_JudicialFileCode],\n    CASE [t1].[Nature] WHEN 953 THEN N''کیفری'' WHEN 954 THEN N''حقوقی'' WHEN 955 THEN N''اداره کار'' WHEN 956 THEN N''ادارات دولتی'' END AS [t1_NatureTitle],\n    [t1].[Subject] AS [t1_Subject],\n    CASE [t1].[Type] WHEN 963 THEN N''له'' WHEN 964 THEN N''علیه'' END AS [t1_TypeTitle],\n    [t1].[JudicialReferenceFileNumber] AS [t1_JudicialReferenceFileNumber],\n    [t2].[Title] AS [t2_Title],\n    [t1].[ReferralDateShamsiDate] AS [t1_ReferralDateShamsiDate],\n    [t1].[RegistrationDateShamsiDate] AS [t1_RegistrationDateShamsiDate],\n    [t1].[Lawyer] AS [t1_Lawyer],\n    [t1].[CreatedByName] AS [t1_CreatedByName],\n    [t1].[CreatedOnShamsiDateTime] AS [t1_CreatedOnShamsiDateTime]\nFROM [Law].[JudicialFile] AS [t1]\nLEFT JOIN [Hrm].[OrgUnit] AS [t2] ON [t2].[Id] = [t1].[ReferralUnitId]\nWHERE @HasFull = 1 OR [t1].[CreatedById] = @CuId", "Parameters": [], "Selects": null}';
    SET @ColumnsJson = N'[{"TableName": null, "ColumnName": "t1_Id", "DisplayName": "شناسه", "Alliance": "t1_Id", "Address": null, "SystemTypeName": "Long", "SelectIndex": 0, "Visible": false, "PrimaryKey": true, "SystemType": 6, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 80, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_CurrentStatus", "DisplayName": "کد وضعیت فعلی", "Alliance": "t1_CurrentStatus", "Address": null, "SystemTypeName": "Int", "SelectIndex": 0, "Visible": false, "PrimaryKey": false, "SystemType": 7, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 80, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_CurrentStatusTitle", "DisplayName": "وضعیت فعلی", "Alliance": "t1_CurrentStatusTitle", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": false, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 150, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_JudicialFileCode", "DisplayName": "کد پرونده", "Alliance": "t1_JudicialFileCode", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 120, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_NatureTitle", "DisplayName": "ماهیت پرونده", "Alliance": "t1_NatureTitle", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 130, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_Subject", "DisplayName": "موضوع پرونده", "Alliance": "t1_Subject", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 200, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_TypeTitle", "DisplayName": "نوع", "Alliance": "t1_TypeTitle", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 100, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_JudicialReferenceFileNumber", "DisplayName": "شماره پرونده مرجع قضایی", "Alliance": "t1_JudicialReferenceFileNumber", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 170, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t2_Title", "DisplayName": "واحد ارجاع", "Alliance": "t2_Title", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 160, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_ReferralDateShamsiDate", "DisplayName": "تاریخ ارجاع", "Alliance": "t1_ReferralDateShamsiDate", "Address": null, "SystemTypeName": "DateShamsi", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 5, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 110, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_RegistrationDateShamsiDate", "DisplayName": "تاریخ ثبت در مرجع قضایی", "Alliance": "t1_RegistrationDateShamsiDate", "Address": null, "SystemTypeName": "DateShamsi", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 5, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 150, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_Lawyer", "DisplayName": "وکیل", "Alliance": "t1_Lawyer", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 150, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_CreatedByName", "DisplayName": "ایجاد کننده", "Alliance": "t1_CreatedByName", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 140, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_CreatedOnShamsiDateTime", "DisplayName": "تاریخ ایجاد", "Alliance": "t1_CreatedOnShamsiDateTime", "Address": null, "SystemTypeName": "DateTimeShamsi", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 4, "SortDirection": 1, "SortOrder": 0, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 150, "Filterable": true, "Sortable": true, "ClassName": ""}]';
    SET @ActionOptions = N'[{"dataActionName": "new", "enable": true, "title": "جدید"}, {"dataActionName": "edit", "enable": true, "title": "ویرایش"}, {"dataActionName": "delete", "enable": true, "title": "حذف"}, {"dataActionName": "exportExcell", "enable": true, "title": "خروجی اکسل"}]';
    SET @Buttons = N'[{"id": "law_judicialfile_attachments", "title": "ضمیمه مدارک", "dataActionName": "attachments", "colorClass": "btn-color-primary", "iconClass": "ki-paper-clip ki-outline", "requiresSelection": true, "requiresMultiSelection": false, "useHtml": false, "html": "", "actionScript": "function(ctx) {\n    var id = ctx && (ctx.primaryKeyValue || (ctx.primaryKeyValues && ctx.primaryKeyValues[0]) || (ctx.selectedRow && (ctx.selectedRow.t1_Id || ctx.selectedRow.id || ctx.selectedRow.Id)));\n    if (!id) { toastr.error(''لطفاً یک ردیف را انتخاب کنید''); return; }\n    appController.addPage(''/Panel/Law/JudicialFileAttachment/ListByParentId?judicialFileId='' + id, true, ''ضمیمه مدارک'');\n}"}]';
    SET @Events = N'{"onSelectedRow": "", "onRowAdded": "function(ctx) {\n    var data = ctx.rowData || {};\n    var status = data.t1_CurrentStatus;\n    var color = null;\n    if (status == 1 || status === ''1'') color = ''#9adb88'';\n    else if (status == 2 || status === ''2'') color = ''#fbaa5b'';\n    else if (status == 3 || status === ''3'') color = ''#8bc3fe'';\n    if (!color || !ctx.table) return;\n    var colIdx = -1;\n    ctx.table.columns().every(function (i) {\n        if (this.dataSrc() === ''_rowNumber'') colIdx = i;\n    });\n    var node = colIdx >= 0 ? ctx.table.cell(ctx.$row, colIdx).node() : ctx.$row.find(''td'').get(0);\n    if (node) $(node).css(''background-color'', color);\n}"}';
    SET @ProfileId = NULL;

    IF EXISTS (SELECT 1 FROM [system].[SavedQuery] WHERE Name = @Name)
    BEGIN
        UPDATE [system].[SavedQuery]
        SET Title = @Title, QueryJson = @QueryJson, ColumnsJson = @ColumnsJson,
            EntityFullName = @EntityFullName, Mode = 1, Type = 1,
            ActionOptions = @ActionOptions, CustomActionButtonsJson = @Buttons, EventScriptsJson = @Events,
            DiagramJson = N'{}', ModifiedById = 1, ModifiedByName = @SeedUser,
            ModifiedDateMiladiDateTime = @Now, ModifiedDateShamsiDateTime = @NowShamsi, IsActive = 1
        WHERE Name = @Name;
        SELECT @ProfileId = Id FROM [system].[SavedQuery] WHERE Name = @Name;
    END
    ELSE
    BEGIN
        INSERT INTO [system].[SavedQuery]
            (Name, Title, QueryJson, ColumnsJson, DiagramJson, CustomActionButtonsJson, EventScriptsJson,
             Mode, Type, EntityFullName, ActionOptions,
             CreatedById, ModifiedById, CreatedByName, ModifiedByName,
             CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
        VALUES
            (@Name, @Title, @QueryJson, @ColumnsJson, N'{}', @Buttons, @Events,
             1, 1, @EntityFullName, @ActionOptions,
             1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1);
        SET @ProfileId = SCOPE_IDENTITY();
    END;
    PRINT N'Law_JudicialFile_List' + N' Id=' + CAST(@ProfileId AS NVARCHAR(20));

    -- ================= Law_JudicialFile_Report =================
    SET @Name = N'Law_JudicialFile_Report';
    SET @Title = N'گزارش کلی پرونده ها';
    SET @QueryJson = N'{"Tables": [], "Relations": [], "Filters": [], "CustomConditions": [], "CustomQuery": "DECLARE @CuId BIGINT = TRY_CAST(@CurrentUserId AS BIGINT);\nDECLARE @HasFull BIT = CASE WHEN EXISTS (\n    SELECT 1\n    FROM system.[User] u\n    CROSS APPLY OPENJSON(ISNULL(u.RoleIds, N''[]'')) j\n    INNER JOIN system.Role r ON r.Id = TRY_CAST(j.value AS bigint)\n    WHERE u.Id = @CuId\n      AND r.Name IN (N''admin'', N''Law.JudicialFileReport.Full'')\n) THEN 1 ELSE 0 END;\n--!--mainsection\nSELECT\n    [t1].[Id] AS [t1_Id],\n    [t1].[CurrentStatus] AS [t1_CurrentStatus],\n    CASE [t1].[CurrentStatus] WHEN 1 THEN N''مختومه بنفع شرکت'' WHEN 2 THEN N''مختومه بر علیه شرکت'' WHEN 3 THEN N''مطرح رسیدگی'' END AS [t1_CurrentStatusTitle],\n    CASE [t1].[Type] WHEN 963 THEN N''له'' WHEN 964 THEN N''علیه'' END AS [t1_TypeTitle],\n    CASE [t1].[Nature] WHEN 953 THEN N''کیفری'' WHEN 954 THEN N''حقوقی'' WHEN 955 THEN N''اداره کار'' WHEN 956 THEN N''ادارات دولتی'' END AS [t1_NatureTitle],\n    [t1].[Subject] AS [t1_Subject],\n    [t1].[JudicialReferenceFileNumber] AS [t1_JudicialReferenceFileNumber],\n    [t2].[Title] AS [t2_Title],\n    [t1].[Lawyer] AS [t1_Lawyer],\n    [tParty].[Txt] AS [tParty_Txt],\n    [t1].[ReferralDateShamsiDate] AS [t1_ReferralDateShamsiDate],\n    [tAuth].[Txt] AS [tAuth_Txt],\n    [tRes].[Title] AS [tRes_Title],\n    [t1].[CreatedOnShamsiDateTime] AS [t1_CreatedOnShamsiDateTime]\nFROM [Law].[JudicialFile] AS [t1]\nLEFT JOIN [Hrm].[OrgUnit] AS [t2] ON [t2].[Id] = [t1].[ReferralUnitId]\nOUTER APPLY (\n    SELECT STUFF((\n        SELECT N'','' + CASE p.[Type] WHEN 967 THEN N''خواهان'' WHEN 968 THEN N''خوانده'' WHEN 969 THEN N''وکیل خواهان'' WHEN 970 THEN N''وکیل خوانده'' WHEN 971 THEN N''شاکی'' WHEN 972 THEN N''متشاکی'' WHEN 1326 THEN N''وکیل شاکی'' WHEN 1327 THEN N''وکیل متشاکی'' END + N'':'' + ISNULL(p.[Fullname], N'''')\n        FROM [Law].[JudicialFileParty] p\n        WHERE p.[JudicialFileId] = [t1].[Id]\n        ORDER BY p.[Id]\n        FOR XML PATH(N''''), TYPE\n    ).value(N''.'', N''nvarchar(max)''), 1, 1, N'''') AS [Txt]\n) AS [tParty]\nOUTER APPLY (\n    SELECT STUFF((\n        SELECT N'','' + ISNULL(ra.[Title], N'''')\n        FROM [Law].[JudicialReviewAuthority] ra\n        WHERE ra.[JudicialFileId] = [t1].[Id]\n        ORDER BY ra.[Id]\n        FOR XML PATH(N''''), TYPE\n    ).value(N''.'', N''nvarchar(max)''), 1, 1, N'''') AS [Txt]\n) AS [tAuth]\nOUTER APPLY (\n    SELECT TOP (1) CASE r.[Result] WHEN 965 THEN N''منتهی به صدور قرار منع تعقیب'' WHEN 966 THEN N''منتهی به صدور قرار موقوفی تعقیب'' WHEN 973 THEN N''منتهی به صدور قرار جلب به دادرسی'' WHEN 974 THEN N''منتهی به صدور رای بدوی'' WHEN 975 THEN N''صدور قرار رد دعوا'' WHEN 976 THEN N''صدور قرار رد دادخواست'' WHEN 977 THEN N''صدور قرار ابطال دادخواست'' WHEN 978 THEN N''صدور قرار عدم استماع دعوا'' WHEN 979 THEN N''صدور قرار اناطه دعوا'' WHEN 980 THEN N''صدور رای'' WHEN 1121 THEN N''صدور قرار کارشناسی'' END AS [Title]\n    FROM [Law].[JudicialFileResult] r\n    WHERE r.[JudicialFileId] = [t1].[Id]\n    ORDER BY r.[Id] DESC\n) AS [tRes]\nWHERE @HasFull = 1 OR [t1].[CreatedById] = @CuId", "Parameters": [], "Selects": null}';
    SET @ColumnsJson = N'[{"TableName": null, "ColumnName": "t1_Id", "DisplayName": "شناسه", "Alliance": "t1_Id", "Address": null, "SystemTypeName": "Long", "SelectIndex": 0, "Visible": false, "PrimaryKey": true, "SystemType": 6, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 80, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_CurrentStatus", "DisplayName": "کد وضعیت فعلی", "Alliance": "t1_CurrentStatus", "Address": null, "SystemTypeName": "Int", "SelectIndex": 0, "Visible": false, "PrimaryKey": false, "SystemType": 7, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 80, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_CurrentStatusTitle", "DisplayName": "وضعیت فعلی", "Alliance": "t1_CurrentStatusTitle", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": false, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 150, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_TypeTitle", "DisplayName": "نوع", "Alliance": "t1_TypeTitle", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "Cu