"مرجع رسیدگی", "Alliance": "tAuth_Txt", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 220, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "tRes_Title", "DisplayName": "آخرین نتیجه", "Alliance": "tRes_Title", "Address": null, "SystemTypeName": "String", "SelectIndex": 0, "Visible": true, "PrimaryKey": false, "SystemType": 0, "SortDirection": null, "SortOrder": null, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 220, "Filterable": true, "Sortable": true, "ClassName": ""}, {"TableName": null, "ColumnName": "t1_CreatedOnShamsiDateTime", "DisplayName": "تاریخ ایجاد", "Alliance": "t1_CreatedOnShamsiDateTime", "Address": null, "SystemTypeName": "DateTimeShamsi", "SelectIndex": 0, "Visible": false, "PrimaryKey": false, "SystemType": 4, "SortDirection": 1, "SortOrder": 0, "GroupBy": false, "Options": [], "OptionSetting": null, "Aggregate": null, "Render": null, "IsCustom": false, "CustomColType": null, "HtmlTemplate": null, "BtnConfig": null, "InputConfig": null, "Width": 150, "Filterable": true, "Sortable": true, "ClassName": ""}]';
    SET @ActionOptions = N'[{"dataActionName": "new", "enable": false, "title": "جدید"}, {"dataActionName": "edit", "enable": false, "title": "ویرایش"}, {"dataActionName": "delete", "enable": false, "title": "حذف"}, {"dataActionName": "exportExcell", "enable": true, "title": "خروجی اکسل"}]';
    SET @Buttons = N'[]';
    SET @Events = N'{"onSelectedRow": "", "onRowAdded": "function(ctx) {\n    var data = ctx.rowData || {};\n    var status = data.t1_CurrentStatus;\n    var color = null;\n    if (status == 1 || status === ''1'') color = ''#9adb88'';\n    else if (status == 2 || status === ''2'') color = ''#fbaa5b'';\n    else if (status == 3 || status === ''3'') color = ''#8bc3fe'';\n    if (!color || !ctx.table) return;\n    var colIdx = -1;\n    ctx.table.columns().every(function (i) {\n        if (this.dataSrc() === ''_rowNumber'') colIdx = i;\n    });\n    var node = colIdx >= 0 ? ctx.table.cell(ctx.$row, colIdx).node() : ctx.$row.find(''td'').get(0);\n    if (node) $(node).css(''background-color'', color);\n}"}';
    SET @ProfileId = NULL;

    IF EXISTS (SELECT 1 FROM [system].[SavedQuery] WHERE Name = @Name)
    BEGIN
        UPDATE [system].[SavedQuery]
        SET Title = @Title, QueryJson = @QueryJson, ColumnsJson = @ColumnsJson,
            EntityFullName = @EntityFullName, Mode = 1, Type = 1,
            ActionOptions = @ActionOptions, CustomActionButtonsJson = @Buttons, EventScriptsJson = @Events,
            DiagramJson = N'{}', ModifiedById = 1, ModifiedByName = @SeedUser,
            ModifiedDateMiladiDateTime = @Now, ModifiedDateShamsiDateTime = @NowShamsi, IsActive = 1
        WHERE Name = @Name;
        SELECT @ProfileId = Id FROM [system].[SavedQuery] WHERE Name = @Name;
    END
    ELSE
    BEGIN
        INSERT INTO [system].[SavedQuery]
            (Name, Title, QueryJson, ColumnsJson, DiagramJson, CustomActionButtonsJson, EventScriptsJson,
             Mode, Type, EntityFullName, ActionOptions,
             CreatedById, ModifiedById, CreatedByName, ModifiedByName,
             CreatedOnMiladiDateTime, CreatedOnShamsiDateTime, ModifiedDateMiladiDateTime, ModifiedDateShamsiDateTime, IsActive)
        VALUES
            (@Name, @Title, @QueryJson, @ColumnsJson, N'{}', @Buttons, @Events,
             1, 1, @EntityFullName, @ActionOptions,
             1, 1, @SeedUser, @SeedUser, @Now, @NowShamsi, @Now, @NowShamsi, 1);
        SET @ProfileId = SCOPE_IDENTITY();
    END;
    PRINT N'Law_JudicialFile_Report' + N' Id=' + CAST(@ProfileId AS NVARCHAR(20));

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
    RAISERROR(@ErrorMessage, 16, 1);
END CATCH;

SELECT q.Id, q.Name, q.Title,
    JSON_VALUE(j.value, '$.Alliance') AS Alliance,
    JSON_VALUE(j.value, '$.DisplayName') AS DisplayName
FROM [system].[SavedQuery] q
CROSS APPLY OPENJSON(q.ColumnsJson) j
WHERE q.Name IN (N'Law_JudicialFile_List', N'Law_JudicialFile_Report')
ORDER BY q.Name, CAST(j.[key] AS int);
